def check_dict_case(dict):
    if not dict:
        return False

    keys = list(dict.keys())

    # Check if all keys are strings
    for key in keys:
        if not isinstance(key, str):
            return False

    # Check if all lower or all upper
    all_lower = all(key == key.lower() for key in keys)
    all_upper = all(key == key.upper() for key in keys)

    return all_lower or all_upper

def count_up_to(n):
    """Implement a function that takes an non-negative integer and returns an array of the first n
    integers that are prime numbers and less than n.
    for example:
    count_up_to(5) => [2,3]
    count_up_to(11) => [2,3,5,7]
    count_up_to(0) => []
    count_up_to(20) => [2,3,5,7,11,13,17,19]
    count_up_to(1) => []
    count_up_to(18) => [2,3,5,7,11,13,17]
    """
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        i = 3
        while i * i <= num:
            if num % i == 0:
                return False
            i += 2
        return True

    result = []
    for num in range(2, n):
        if is_prime(num):
            result.append(num)

    return result

def histogram(test):
    if not test:
        return {}

    letters = test.split()

    # Count frequencies
    freq = {}
    for letter in letters:
        freq[letter] = freq.get(letter, 0) + 1

    # Find maximum frequency
    max_count = max(freq.values())

    # Return all letters with maximum frequency
    result = {}
    for letter, count in freq.items():
        if count == max_count:
            result[letter] = count

    return result

def match_parens(lst):
    def analyze(s):
        min_bal = 0
        bal = 0
        for c in s:
            if c == '(':
                bal += 1
            else:
                bal -= 1
            min_bal = min(min_bal, bal)
        return (min_bal, bal)

    a, b = lst[0], lst[1]
    min_a, final_a = analyze(a)
    min_b, final_b = analyze(b)

    # Try a + b
    # a must not go negative, and b starting from final_a must not go negative
    if min_a >= 0 and min_b + final_a >= 0 and final_a + final_b == 0:
        return 'Yes'

    # Try b + a
    if min_b >= 0 and min_a + final_b >= 0 and final_a + final_b == 0:
        return 'Yes'

    return 'No'

def split_words(txt):
    '''
    Given a string of words, return a list of words split on whitespace, if no whitespaces exists in the text you
    should split on commas ',' if no commas exists you should return the number of lower-case letters with odd order in the
    alphabet, ord('a') = 0, ord('b') = 1, ... ord('z') = 25
    Examples
    split_words("Hello world!") ➞ ["Hello", "world!"]
    split_words("Hello,world!") ➞ ["Hello", "world!"]
    split_words("abcdef") == 3 
    '''
    # Check for whitespace
    if any(c.isspace() for c in txt):
        return txt.split()

    # Check for commas
    if ',' in txt:
        return txt.split(',')

    # Count lowercase letters with odd order in alphabet
    count = 0
    for c in txt:
        if c.islower():
            order = ord(c) - ord('a')
            if order % 2 == 1:
                count += 1

    return count

def minPath(grid, k):
    n = len(grid)

    # Find the minimum value and its position
    min_val = float('inf')
    min_pos = None
    for i in range(n):
        for j in range(n):
            if grid[i][j] < min_val:
                min_val = grid[i][j]
                min_pos = (i, j)

    if k == 1:
        return [min_val]

    # Find minimum neighbor of min_pos
    r, c = min_pos
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    min_neighbor = float('inf')

    for dr, dc in directions:
        nr, nc = r + dr, c + dc
        if 0 <= nr < n and 0 <= nc < n:
            min_neighbor = min(min_neighbor, grid[nr][nc])

    # Build the path alternating min_val and min_neighbor
    result = []
    for i in range(k):
        if i % 2 == 0:
            result.append(min_val)
        else:
            result.append(min_neighbor)

    return result

def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,
    """
    def to_float(val):
        if isinstance(val, str):
            return float(val.replace(',', '.'))
        else:
            return float(val)

    a_float = to_float(a)
    b_float = to_float(b)

    if a_float > b_float:
        return a
    elif b_float > a_float:
        return b
    else:
        return None

def sum_squares(lst):
    total = 0
    for i, val in enumerate(lst):
        if i % 3 == 0:
            total += val ** 2
        elif i % 4 == 0:
            total += val ** 3
        else:
            total += val
    return total

def get_max_triples(n):
    count_0 = (n + 1) // 3  # numbers with remainder 0 mod 3
    count_1 = n - count_0   # numbers with remainder 1 mod 3

    # Number of ways to choose 3 from count_0 plus ways to choose 3 from count_1
    def comb3(x):
        if x < 3:
            return 0
        return x * (x - 1) * (x - 2) // 6

    return comb3(count_0) + comb3(count_1)

def sorted_list_sum(lst):
    # Filter out strings with odd lengths
    even_length_strings = [s for s in lst if len(s) % 2 == 0]
    # Sort by length first, then alphabetically
    return sorted(even_length_strings, key=lambda x: (len(x), x))

def cycpattern_check(a, b):
    if not b:
        return True
    if len(b) > len(a):
        return False

    # Generate all rotations of b
    n = len(b)
    for i in range(n):
        rotation = b[i:] + b[:i]
        if rotation in a:
            return True
    return False

def even_odd_count(num):
    """Given an integer. return a tuple that has the number of even and odd digits respectively.

     Example:
        even_odd_count(-12) ==> (1, 1)
        even_odd_count(123) ==> (1, 2)
    """
    even_count = 0
    odd_count = 0

    for digit in str(abs(num)):
        if int(digit) % 2 == 0:
            even_count += 1
        else:
            odd_count += 1

    return (even_count, odd_count)

def do_algebra(operator, operand):
    # Build the expression string
    expression = str(operand[0])
    for i, op in enumerate(operator):
        expression += ' ' + op + ' ' + str(operand[i + 1])

    # Evaluate and return
    return eval(expression)

import hashlib

def string_to_md5(text):
    """
    Given a string 'text', return its md5 hash equivalent string.
    If 'text' is an empty string, return None.

    >>> string_to_md5('Hello world') == '3e25960a79dbc69b674cd4ec67a72c62'
    """
    if text == "":
        return None
    return hashlib.md5(text.encode('utf-8')).hexdigest()
